use verus::prelude::*;

/// Finds the index of the minimum element in the slice `a`
/// starting from index `lo` through the end of the slice.
///
/// # Panics
///
/// Panics if `a` is empty or if `lo >= a.len()`.
#[requires(a.len() > 0)]
#[requires(lo < a.len())]
#[ensures(|result: usize| lo <= result && result < a.len())]
#[ensures(|result: usize| 
    forall(|j: usize| (j >= lo && j < a.len()) ==> a[result] <= a[j])
)]
fn find_min(a: &[i32], lo: usize) -> usize {
    // These runtime asserts line up with our requires above
    assert!(a.len() > 0, "array must be non-empty");
    assert!(lo < a.len(), "starting index out of bounds");

    let mut min_idx = lo;
    // We iterate i from lo+1 up to a.len(), maintaining:
    //   1) lo < = min_idx < i <= a.len()
    //   2) for all j in [lo, i), a[min_idx] <= a[j]
    for i in (lo + 1)..a.len() {
        #[invariant(lo <= min_idx && min_idx < i)]
        #[invariant(i <= a.len())]
        #[invariant(forall(|j: usize| (j >= lo && j < i) ==> a[min_idx] <= a[j]))]
        #[decreases(a.len() - i)]
        {
            if a[i] < a[min_idx] {
                min_idx = i;
            }
        }
    }
    min_idx
}

